/// <remarks>
/// Every id/label pair <see cref="MermaidRenderer"/> can emit — a task container's <c>subgraph
/// task_&lt;base&gt;["..."]</c>, a plan-level bracket's <c>subgraph plan_preflights["..."]</c>/
/// <c>plan_guardrails["..."]</c>, and every preflight/guardrail leaf's
/// <c>..._pf_&lt;n&gt;["..."]</c>/<c>..._gr_&lt;n&gt;["..."]</c> — shares the exact same
/// <c>id["label"]</c> shape: a Mermaid node/subgraph id is always <c>[A-Za-z0-9_]+</c> (every
/// other character is sanitized to <c>_</c>), immediately followed by its label in
/// double-quoted square brackets (a label can never contain a raw <c>"</c> — it is always
/// HTML-escaped first). That means one non-anchored regex over the WHOLE source finds every
/// id/label pair regardless of whether the line is a <c>subgraph</c> declaration or a leaf
/// <c>:::class</c> node — no separate cases for containers vs. leaves are needed. Labels are
/// HTML-decoded back to the plain text a user actually sees on screen and types into the search
/// box (the escaping is only for safe embedding in the Mermaid/SVG source).
/// </remarks>
private static string BuildSearchIndexJson(string mermaidSource)
{
    var index = new Dictionary<string, string>(StringComparer.Ordinal);
    foreach (Match match in NodeIdLabelPattern.Matches(mermaidSource))
    {
        index[match.Groups["id"].Value] = HtmlDecodeLabel(match.Groups["label"].Value);
    }

    return JsonSerializer.Serialize(index, new JsonSerializerOptions
    {
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping,
    });
}

// Matches every `<id>["<label>"]` shape MermaidRenderer emits (subgraph container declarations
// and leaf check nodes alike — see BuildSearchIndexJson remarks). Ids are always [A-Za-z0-9_]+
// (MermaidRenderer.Sanitize); a label's own quotes are always HTML-escaped, so `[^"]*` safely
// captures up to the closing quote regardless of what other characters (including brackets) the
// label itself contains.
private static readonly Regex NodeIdLabelPattern =
    new("(?<id>[A-Za-z0-9_]+)\\[\"(?<label>[^\"]*)\"\\]", RegexOptions.Compiled);

// Reverses MermaidRenderer.Quote's HTML-escaping, in the opposite order it was applied, so the
// search index holds the plain text a user sees on screen rather than the Mermaid-escaped form.
private static string HtmlDecodeLabel(string escaped) =>
    escaped
        .Replace("&#35;", "#", StringComparison.Ordinal)
        .Replace("&quot;", "\"", StringComparison.Ordinal)
        .Replace("&gt;", ">", StringComparison.Ordinal)
        .Replace("&lt;", "<", StringComparison.Ordinal)
        .Replace("&amp;", "&", StringComparison.Ordinal);

