// Diagram search (issue #220): substring-matches the typed query (case-insensitive) against every
// entry in `searchIndex` (id -> visible label, built by BuildSearchIndexJson — see class remarks),
// toggles each matching node's class to 'search-match' and every other node's to 'search-dim' (pure
// class toggling, no Mermaid re-render), updates the "N of M" counter, and auto pans/zooms the FIRST
// match into view via the pan-zoom instance API: pz.getSizes() (viewport size + current zoom) and
// pz.zoom()/pz.pan() to re-center on the match's own bounding box.
let searchMatches = [];
let searchCursor = 0;

// Resolve a search-index id to its SVG element: task containers and non-empty plan-level brackets
// keep their raw id on the <g class="cluster">; leaf check nodes (and an empty plan bracket, which
// Mermaid draws as a plain node) are ided "flowchart-<logicalId>-<counter>" instead (same fallback
// findStatusTarget above uses for the live-status overlay).
function findSearchTarget(id) {
  if (!svgEl) return null;
  return svgEl.querySelector('[id="' + id + '"]') || svgEl.querySelector('[id^="flowchart-' + id + '-"]');
}

function updateSearchCount() {
  document.getElementById('search-count').textContent =
    searchMatches.length ? (searchCursor + 1) + ' of ' + searchMatches.length : '';
}

// Re-center the pan-zoom viewport on target's CURRENT on-screen box, at the CURRENT zoom level
// (never changes zoom — only pans) — used by next/prev, which move between already-computed
// matches without recomputing them.
function centerOnSearchMatch(target) {
  if (!pz || !target) return;
  const box = target.getBBox();
  const sizes = pz.getSizes();
  const zoom = sizes.realZoom;
  pz.pan({
    x: sizes.width / 2 - (box.x + box.width / 2) * zoom,
    y: sizes.height / 2 - (box.y + box.height / 2) * zoom,
  });
}

function runSearch(query) {
  if (svgEl) {
    svgEl.querySelectorAll('.search-match, .search-dim').forEach((node) => {
      node.classList.remove('search-match', 'search-dim');
    });
  }

  const q = query.trim().toLowerCase();
  searchMatches = [];
  searchCursor = 0;

  if (svgEl && q) {
    for (const [id, label] of Object.entries(searchIndex)) {
      const target = findSearchTarget(id);
      if (!target) continue; // id not present in this render — no node to highlight (defensive)
      const isMatch = id.toLowerCase().includes(q) || String(label).toLowerCase().includes(q);
      target.classList.add(isMatch ? 'search-match' : 'search-dim');
      if (isMatch) searchMatches.push(target);
    }
  }

  updateSearchCount();
  if (searchMatches.length) {
    const box = searchMatches[0].getBBox();
    const sizes = pz.getSizes();
    const zoom = sizes.realZoom;
    pz.zoom(zoom);
    pz.pan({
      x: sizes.width / 2 - (box.x + box.width / 2) * zoom,
      y: sizes.height / 2 - (box.y + box.height / 2) * zoom,
    });
  }
}
